// Command specreading is the second, mechanical reading of the normative
// tables of the CABAC engine: it parses the text layer of ITU-T H.265 (V11)
// (01/2026) as `pdftotext -raw` prints it and writes spec_reading_test.go.
//
//	pdftotext -raw T-REC-H.265-202601-I!!PDF-E.pdf spec.raw.txt
//	go run ./internal/cabac/testdata/specreading spec.raw.txt > internal/cabac/spec_reading_test.go
//
// It reads Tables 9-5 to 9-42 (the "initValue" rows), Table 9-52 and Table 9-53.
// The production tables were typed by hand from the page layout; this program
// shares nothing with that reading but the document. Only the numbers are
// written out, never the document's text.
package main

import (
	"bufio"
	"fmt"
	"os"
	"regexp"
	"sort"
	"strconv"
	"strings"
)

var (
	initHead = regexp.MustCompile(`^Table (9-\d+) – Values of initValue for ctxIdx`)
	tokenRe  = regexp.MustCompile(`^\d+`)
)

// value reads one table cell. The page footer is glued to the last cell of a
// table that ends a page ("154212 Rec. ITU-T", "93Rec."): cells are at most
// three digits and at most 255, so a longer run of digits is cut after the
// third digit, or after the second when three would exceed 255.
func value(tok string) int {
	digits := tokenRe.FindString(tok)
	if digits == "" {
		panic("no digits in " + tok)
	}
	if len(digits) > 3 {
		digits = digits[:3]
	}
	v, _ := strconv.Atoi(digits)
	if v > 255 {
		v, _ = strconv.Atoi(digits[:2])
	}
	return v
}

func ints(line string) []int {
	var out []int
	for _, f := range strings.Fields(line) {
		if v, err := strconv.Atoi(f); err == nil {
			out = append(out, v)
		} else {
			return nil
		}
	}
	return out
}

func main() {
	f, err := os.Open(os.Args[1])
	if err != nil {
		panic(err)
	}
	defer f.Close()
	var lines []string
	sc := bufio.NewScanner(f)
	sc.Buffer(make([]byte, 1<<20), 1<<20)
	for sc.Scan() {
		lines = append(lines, sc.Text())
	}

	init := map[string][]int{}
	for i := 0; i < len(lines); i++ {
		m := initHead.FindStringSubmatch(lines[i])
		if m == nil || strings.Contains(lines[i], "....") {
			continue
		}
		name := "Table " + m[1]
		for j := i + 1; j < len(lines) && !strings.HasPrefix(lines[j], "Table "); j++ {
			if !strings.HasPrefix(lines[j], "initValue") {
				continue
			}
			want := len(ints(lines[j-1]))
			toks := strings.Fields(lines[j])[1:]
			if want == 0 || len(toks) < want {
				panic(fmt.Sprintf("%s: row %q after %q", name, lines[j], lines[j-1]))
			}
			for _, t := range toks[:want] {
				init[name] = append(init[name], value(t))
			}
		}
	}

	var lps [64][4]int
	var tmps, tlps [64]int
	for i := 0; i < len(lines); i++ {
		switch {
		case strings.HasPrefix(lines[i], "Table 9-52 –") && !strings.Contains(lines[i], "...."):
			for j := i + 1; !strings.HasPrefix(lines[j], "Table 9-53"); j++ {
				line := strings.Replace(lines[j], "238 Rec. ITU-T H.265 (V11) (01/2026)", "", 1)
				v := ints(line)
				if len(v) != 10 {
					continue
				}
				copy(lps[v[0]][:], v[1:5])
				copy(lps[v[5]][:], v[6:10])
			}
		case strings.HasPrefix(lines[i], "Table 9-53 –") && !strings.Contains(lines[i], "...."):
			for j := i + 1; j+2 < len(lines) && strings.HasPrefix(lines[j], "pStateIdx"); j += 3 {
				idx := ints(strings.TrimPrefix(lines[j], "pStateIdx"))
				l := ints(strings.TrimPrefix(lines[j+1], "transIdxLps"))
				m := ints(strings.TrimPrefix(lines[j+2], "transIdxMps"))
				for k, s := range idx {
					tlps[s], tmps[s] = l[k], m[k]
				}
			}
		}
	}

	names := make([]string, 0, len(init))
	for n := range init {
		names = append(names, n)
	}
	sort.Slice(names, func(a, b int) bool {
		na, _ := strconv.Atoi(strings.TrimPrefix(names[a], "Table 9-"))
		nb, _ := strconv.Atoi(strings.TrimPrefix(names[b], "Table 9-"))
		return na < nb
	})

	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	fmt.Fprintln(w, "// Code generated by testdata/specreading from the text layer of ITU-T H.265")
	fmt.Fprintln(w, "// (V11) (01/2026); DO NOT EDIT.")
	fmt.Fprintln(w)
	fmt.Fprintln(w, "package cabac")
	fmt.Fprintln(w)
	fmt.Fprintln(w, "// specInitValue is the second reading of Tables 9-5 to 9-42: the initValue row(s)")
	fmt.Fprintln(w, "// of each table, in ctxIdx order.")
	fmt.Fprintln(w, "var specInitValue = map[string][]uint8{")
	for _, n := range names {
		fmt.Fprintf(w, "\t%q: {", n)
		for i, v := range init[n] {
			if i > 0 {
				fmt.Fprint(w, ", ")
			}
			fmt.Fprint(w, v)
		}
		fmt.Fprintln(w, "},")
	}
	fmt.Fprintln(w, "}")
	fmt.Fprintln(w)
	fmt.Fprintln(w, "// specRangeTabLps is the second reading of Table 9-52.")
	fmt.Fprintln(w, "var specRangeTabLps = [64][4]uint8{")
	for _, r := range lps {
		fmt.Fprintf(w, "\t{%d, %d, %d, %d},\n", r[0], r[1], r[2], r[3])
	}
	fmt.Fprintln(w, "}")
	fmt.Fprintln(w)
	fmt.Fprintln(w, "// specTransIdxLps and specTransIdxMps are the second reading of Table 9-53.")
	for _, t := range []struct {
		name string
		v    [64]int
	}{{"specTransIdxLps", tlps}, {"specTransIdxMps", tmps}} {
		fmt.Fprintf(w, "var %s = [64]uint8{", t.name)
		for i, v := range t.v {
			if i > 0 {
				fmt.Fprint(w, ", ")
			}
			fmt.Fprint(w, v)
		}
		fmt.Fprintln(w, "}")
	}
}
